/**
 * 必背考点模块的内置数据 —— 原始来源是 outputs/ 下三份「5 周冲刺保底方案」HTML。
 *
 * ⚠️ 2026-09-23 起：那三份 HTML 与《必背考点模块-迁移工作量审计》已随 outputs/ 清理删除，
 * 抽取脚本（/tmp/mr_*_extract.py、/tmp/mr_build_ts.py）也已不存在。
 * 因此 **本文件即权威源**：内容改动直接改这里，再跑 `pnpm db:must-read`（按 origin 先删后插）重灌。
 * 注意 DB 与本文件必须双侧同步 —— 只改一边会被下次灌库覆盖。
 * 历史背景：当初以 HTML 为准，是因为 /tmp/gen_*_sprint.py 落后 6 条补录考点
 * （即《迁移工作量审计》中的「坑 1」）；该脚本同样已不存在。
 */

export interface MustReadItem {
  /** 卡片标题：政治=考点题面 / 英语=单词 / 数学=公式名 */
  title: string;
  /** 卡片正文：政治=答案 / 英语=释义 / 数学=LaTeX 原串；MATERIAL 条目为章节 HTML */
  content: string;
  /** MUST_READ=必背卡，MATERIAL=章节正文 */
  itemType: 'MUST_READ' | 'MATERIAL';
  /** 文档顺序：章节 → 分组 → 组内，页面按它排序 */
  sortOrder: number;
  /** 出处（政治为「2025 年 · 第 11 题 · 正确项「…」」） */
  source: string | null;
  tags: string[];
  /** 结构化附加数据：公共 chapter/chapterIntro/section/group；政治 refs=关联真题卡；英语 ipa/say/cn；数学 tex/note/tail */
  extra: Record<string, unknown>;
}

export interface MustReadSubject {
  /** 必须与 subjects 表里的名字一致（高等数学一在库里带全角括号） */
  subjectName: string;
  /** 展示名（前端统一用不带括号的「高等数学一」） */
  display: string;
  sourceFile: string;
  items: MustReadItem[];
}

